class LFUCache {
  private m = new Map<number, { val: number; cnt: number; last: number }>();
  private clock = 0;
  constructor(private capacity: number) {}

  get(key: number): number {
    const e = this.m.get(key);
    if (!e) return -1;
    e.cnt++;
    e.last = ++this.clock;
    return e.val;
  }

  put(key: number, value: number): void {
    const e = this.m.get(key);
    if (e) {
      e.val = value;
      e.cnt++;
      e.last = ++this.clock;
      return;
    }
    if (this.m.size === this.capacity) {
      let victim = -1, best: { cnt: number; last: number } | null = null;
      for (const [k, x] of this.m) {
        if (!best || x.cnt < best.cnt || (x.cnt === best.cnt && x.last < best.last)) {
          best = x;
          victim = k;
        }
      }
      this.m.delete(victim);
    }
    this.m.set(key, { val: value, cnt: 1, last: ++this.clock });
  }
}

