class LFUCache {
  private vals = new Map<number, number>();
  private count = new Map<number, number>();
  // count -> keys with that count; a Set iterates in insertion order, oldest use first
  private buckets = new Map<number, Set<number>>();
  private minCount = 0;
  constructor(private capacity: number) {}

  private bucket(c: number): Set<number> {
    let b = this.buckets.get(c);
    if (!b) {
      b = new Set();
      this.buckets.set(c, b);
    }
    return b;
  }

  private touch(key: number): void {
    const c = this.count.get(key)!;
    const b = this.buckets.get(c)!;
    b.delete(key);
    if (b.size === 0) {
      this.buckets.delete(c);
      if (this.minCount === c) this.minCount = c + 1;
    }
    this.count.set(key, c + 1);
    this.bucket(c + 1).add(key);
  }

  get(key: number): number {
    if (!this.vals.has(key)) return -1;
    this.touch(key);
    return this.vals.get(key)!;
  }

  put(key: number, value: number): void {
    if (this.vals.has(key)) {
      this.vals.set(key, value);
      this.touch(key);
      return;
    }
    if (this.vals.size === this.capacity) {
      const b = this.buckets.get(this.minCount)!;
      const victim = b.values().next().value!;
      b.delete(victim);
      if (b.size === 0) this.buckets.delete(this.minCount);
      this.vals.delete(victim);
      this.count.delete(victim);
    }
    this.vals.set(key, value);
    this.count.set(key, 1);
    this.bucket(1).add(key);
    this.minCount = 1;
  }
}

