class LFUCache:
    def __init__(self, capacity: int):
        self.cap = capacity
        self.vals = {}
        self.count = {}
        # count -> OrderedDict of keys, oldest use first
        self.buckets = defaultdict(OrderedDict)
        self.min_count = 0

    def _touch(self, key: int) -> None:
        c = self.count[key]
        b = self.buckets[c]
        del b[key]
        if not b:
            del self.buckets[c]
            if self.min_count == c:
                self.min_count = c + 1
        self.count[key] = c + 1
        self.buckets[c + 1][key] = None

    def get(self, key: int) -> int:
        if key not in self.vals:
            return -1
        self._touch(key)
        return self.vals[key]

    def put(self, key: int, value: int) -> None:
        if key in self.vals:
            self.vals[key] = value
            self._touch(key)
            return
        if len(self.vals) == self.cap:
            b = self.buckets[self.min_count]
            victim, _ = b.popitem(last=False)
            if not b:
                del self.buckets[self.min_count]
            del self.vals[victim]
            del self.count[victim]
        self.vals[key] = value
        self.count[key] = 1
        self.buckets[1][key] = None
        self.min_count = 1

